import{_ as e,o as t,c as i,ag as n}from"./chunks/framework.D5hoimZQ.js";const b=JSON.parse('{"title":"科学日报 · 2026-10-26（生物医学 / 肿瘤免疫 / 线粒体适应性）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/science-daily-2026-10-26-biomed.md","filePath":"topics/biomedicine/science-daily-2026-10-26-biomed.md"}'),s={name:"topics/biomedicine/science-daily-2026-10-26-biomed.md"};function r(c,o,d,g,a,l){return t(),i("div",null,[...o[0]||(o[0]=[n('<h1 id="科学日报-·-2026-10-26-生物医学-肿瘤免疫-线粒体适应性" tabindex="-1">科学日报 · 2026-10-26（生物医学 / 肿瘤免疫 / 线粒体适应性） <a class="header-anchor" href="#科学日报-·-2026-10-26-生物医学-肿瘤免疫-线粒体适应性" aria-label="Permalink to &quot;科学日报 · 2026-10-26（生物医学 / 肿瘤免疫 / 线粒体适应性）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-26.md</code> — 第45期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-biomed</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-26-瘤内「热敏水凝胶」——一边杀死肿瘤-一边给耗竭的-cd8-t-细胞换「好线粒体」" tabindex="-1">科学日报 2026-10-26：瘤内「热敏水凝胶」——一边杀死肿瘤，一边给耗竭的 CD8⁺T 细胞换「好线粒体」 <a class="header-anchor" href="#科学日报-2026-10-26-瘤内「热敏水凝胶」——一边杀死肿瘤-一边给耗竭的-cd8-t-细胞换「好线粒体」" aria-label="Permalink to &quot;科学日报 2026-10-26：瘤内「热敏水凝胶」——一边杀死肿瘤，一边给耗竭的 CD8⁺T 细胞换「好线粒体」&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-26.md</code> ｜ DOI: 10.1126/sciadv.adz0039 ｜ Science Advances (2026)</p></blockquote><ul><li>问题：<strong>CD8⁺T 细胞耗竭</strong>（exhaustion）由<strong>线粒体功能障碍</strong>驱动，是<strong>癌症免疫治疗的主要障碍</strong>。</li><li>本工作：一种<strong>原位成胶（in situ forming）<strong>的热敏复合凝胶 <strong>MTC Gel</strong>（基于 <strong>d-α-生育酚聚乙二醇琥珀酸酯 TPGS</strong>），用</strong>「双管齐下」<strong>策略</strong>保住线粒体适应性（mitochondrial fitness）</strong>： <ul><li><strong>管一（打肿瘤）</strong>：瘤内注射后在<strong>生理温度快速成胶并解离</strong>，产生<strong>高局部浓度 TPGS</strong>，<strong>靶向癌细胞线粒体</strong>触发<strong>促死亡线粒体自噬（prodeath mitophagy）</strong> → 诱发<strong>强烈的免疫原性细胞死亡（ICD）</strong>，并<strong>阻断隧道纳米管（tunneling nanotube）介导的「线粒体劫持」</strong>（癌细胞从 T 细胞偷线粒体）；</li><li><strong>管二（救 T 细胞）</strong>：凝胶释放<strong>负载 NLG919 的杂化纳米粒</strong>，<strong>协同恢复</strong>被 <strong>IDO1</strong> 抑制的 CD8⁺T 细胞<strong>线粒体生成（biogenesis）</strong>。</li></ul></li><li>结果：在<strong>多个小鼠肿瘤模型</strong>中，MTC Gel <strong>降低 CD8⁺T 耗竭</strong>、<strong>增强效应与杀伤功能</strong>，产生<strong>强抗肿瘤活性</strong>；作者将其定位为<strong>可临床转化的新一代 ICD 免疫治疗平台</strong>。</li><li>洞察（对本库 <code>biomedicine</code> × <code>ai-brain</code>）： <ol><li><strong>「同一个器官在两方手里，就变成战场」</strong> —— 本条的核心是<strong>线粒体既是癌细胞的燃料、也是 T 细胞的燃料</strong>，且<strong>癌细胞会主动「偷」T 细胞的线粒体</strong>（隧道纳米管劫持）。于是疗法必须<strong>同一次给药里做两件方向相反的事</strong>（杀癌细胞的线粒体 + 修 T 细胞的线粒体）。这与 10-25「BAX–BAK 下游分成细胞色素 c 与 mtDNA 两条通道、可只关炎症性死亡而保留凋亡」（<code>topics/biomedicine/science-daily-2026-10-25-biomed.md</code>）是<strong>同一条线粒体主线</strong>：<strong>线粒体正在从一个『能量细胞器』变成『可被定向调控的免疫/死亡开关』</strong>。</li><li><strong>可迁移判据</strong>：<strong>当一个资源（此处线粒体）同时是敌人和友军的命脉时，不要做全身性调节，而要做「局部 + 双向」的差异化干预</strong>（此处瘤内 + 两种载荷）。对照 10-23「ECHO 电催化闭环器件把血糖选择性氧化为经肾清除的葡萄糖酸」（<code>topics/biomedicine/science-daily-2026-10-23-biomed.md</code>）：二者都是<strong>把「不可控的全身代谢/免疫」改造成「可局部闭环的器件化干预」</strong>。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/biomedicine/index.md</code> ｜ 第45期 科学板块</p></blockquote><p>关键词：CD8⁺T 细胞耗竭、线粒体适应性 mitochondrial fitness、MTC Gel、TPGS 热敏水凝胶、原位成胶、瘤内注射、促死亡线粒体自噬、免疫原性细胞死亡 ICD、隧道纳米管线粒体劫持、NLG919、IDO1、线粒体生成、肿瘤免疫治疗、局部双向干预、线粒体作为可调控开关</p><p>关联：<code>topics/biomedicine/science-daily-2026-10-25-biomed.md</code>（BAX–BAK / mtDNA 外流）、<code>topics/biomedicine/science-daily-2026-10-23-biomed.md</code>（ECHO 血糖电催化闭环）、<code>topics/biomedicine/science-daily-2026-10-24-biomed.md</code>、<code>topics/biomedicine/index.md</code></p>',10)])])}const p=e(s,[["render",r]]);export{b as __pageData,p as default};
